<?php
declare(strict_types=1);$active_module='hotel_team';require_once __DIR__.'/layout.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$message='';$error='';try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$action=$_POST['action']??'';if($action==='housekeeping'){$pdo->prepare('INSERT INTO housekeeping_tasks(property_id,physical_room_id,task_type,priority,assigned_to,due_at,notes) VALUES(?,?,?,?,?,?,?)')->execute([(int)$_POST['property_id'],(int)$_POST['physical_room_id']?:null,$_POST['task_type']??'cleaning',$_POST['priority']??'normal',trim((string)$_POST['assigned_to'])?:null,$_POST['due_at']?:null,trim((string)$_POST['notes'])?:null]);$message='Kat hizmetleri görevi oluşturuldu.';}if($action==='maintenance'){$pdo->prepare('INSERT INTO maintenance_tickets(property_id,physical_room_id,title,description,priority,assigned_to) VALUES(?,?,?,?,?,?)')->execute([(int)$_POST['property_id'],(int)$_POST['physical_room_id']?:null,trim((string)$_POST['title']),trim((string)$_POST['description'])?:null,$_POST['priority']??'normal',trim((string)$_POST['assigned_to'])?:null]);$message='Teknik servis kaydı oluşturuldu.';}if($action==='service'){$pdo->prepare('INSERT INTO property_services(property_id,service_type,name,duration_minutes,capacity,price,currency) VALUES(?,?,?,?,?,?,?)')->execute([(int)$_POST['property_id'],$_POST['service_type']??'activity',trim((string)$_POST['name']),(int)$_POST['duration']?:null,(int)$_POST['capacity']?:null,(float)$_POST['price'],$_POST['currency']??'EUR']);$message='Ek hizmet tanımlandı.';}if($action==='task_status'){$table=$_POST['kind']==='maintenance'?'maintenance_tickets':'housekeeping_tasks';$status=trim((string)$_POST['status']);if(!in_array($status,['assigned','in_progress','inspected','completed','resolved','cancelled'],true))throw new RuntimeException('Geçersiz görev durumu.');$pdo->prepare("UPDATE $table SET status=?,completed_at=CASE WHEN ? IN ('completed','resolved') THEN now() ELSE completed_at END WHERE id=?")->execute([$status,$status,(int)$_POST['id']]);$message='Görev durumu güncellendi.';}}}catch(Throwable $e){$error=$e->getMessage();}$q=$pdo->prepare("SELECT pr.id,pr.room_number,p.id property_id,p.name property_name FROM physical_rooms pr JOIN properties p ON p.id=pr.property_id WHERE p.supplier_id=? AND p.property_type='hotel' ORDER BY p.name,pr.room_number");$q->execute([$u['supplier_id']]);$rooms=$q->fetchAll();$hotels=[];foreach($rooms as $r)$hotels[$r['property_id']]=$r['property_name'];$q=$pdo->prepare('SELECT h.*,p.name property_name,pr.room_number FROM housekeeping_tasks h JOIN properties p ON p.id=h.property_id LEFT JOIN physical_rooms pr ON pr.id=h.physical_room_id WHERE p.supplier_id=? ORDER BY CASE WHEN h.status IN (\'completed\',\'inspected\') THEN 1 ELSE 0 END,h.created_at DESC LIMIT 100');$q->execute([$u['supplier_id']]);$housekeeping=$q->fetchAll();$q=$pdo->prepare('SELECT m.*,p.name property_name,pr.room_number FROM maintenance_tickets m JOIN properties p ON p.id=m.property_id LEFT JOIN physical_rooms pr ON pr.id=m.physical_room_id WHERE p.supplier_id=? ORDER BY CASE WHEN m.status IN (\'resolved\',\'cancelled\') THEN 1 ELSE 0 END,m.created_at DESC LIMIT 100');$q->execute([$u['supplier_id']]);$maintenance=$q->fetchAll();$q=$pdo->prepare('SELECT s.*,p.name property_name FROM property_services s JOIN properties p ON p.id=s.property_id WHERE p.supplier_id=? ORDER BY s.id DESC');$q->execute([$u['supplier_id']]);$services=$q->fetchAll();supply_start('Kat hizmetleri, teknik servis & ek hizmetler',$active_module);?><section class="page-intro"><p>Oda temizliği, kalite kontrolü, teknik arıza ve otel içi satılabilir hizmetleri aynı operasyon ekranından yönetin.</p></section><?php if($message):?><p class="save-success">✓ <?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><section class="next-module"><h2>Kat hizmetleri görevi</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="housekeeping"><div class="form-row"><label>Otel<select name="property_id"><?php foreach($hotels as $id=>$name):?><option value="<?=$id?>"><?=htmlspecialchars($name)?></option><?php endforeach;?></select></label><label>Oda<select name="physical_room_id"><option value="">Genel alan</option><?php foreach($rooms as $r):?><option value="<?=$r['id']?>"><?=htmlspecialchars($r['property_name'].' · '.$r['room_number'])?></option><?php endforeach;?></select></label><label>Görev<select name="task_type"><option value="cleaning">Temizlik</option><option value="inspection">Kontrol</option><option value="laundry">Çamaşır</option><option value="turndown">Turn-down</option></select></label><label>Öncelik<select name="priority"><option>normal</option><option>high</option><option>urgent</option></select></label></div><input name="assigned_to" placeholder="Atanan personel"><input name="due_at" type="datetime-local"><textarea name="notes" placeholder="Not"></textarea><button>Görev oluştur</button></form></section><section class="next-module"><h2>Teknik servis</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="maintenance"><div class="form-row"><label>Otel<select name="property_id"><?php foreach($hotels as $id=>$name):?><option value="<?=$id?>"><?=htmlspecialchars($name)?></option><?php endforeach;?></select></label><label>Oda<select name="physical_room_id"><option value="">Genel alan</option><?php foreach($rooms as $r):?><option value="<?=$r['id']?>"><?=htmlspecialchars($r['property_name'].' · '.$r['room_number'])?></option><?php endforeach;?></select></label><input name="title" placeholder="Arıza başlığı" required><select name="priority"><option>normal</option><option>high</option><option>urgent</option></select></div><input name="assigned_to" placeholder="Atanan teknik ekip"><textarea name="description" placeholder="Açıklama"></textarea><button>Arıza kaydı aç</button></form></section><section class="next-module"><h2>Satılabilir ek hizmet</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="service"><div class="form-row"><label>Otel<select name="property_id"><?php foreach($hotels as $id=>$name):?><option value="<?=$id?>"><?=htmlspecialchars($name)?></option><?php endforeach;?></select></label><select name="service_type"><option value="spa">SPA</option><option value="restaurant">Restoran</option><option value="activity">Aktivite</option><option value="transfer">Transfer</option><option value="beach">Plaj/Pavilion</option></select><input name="name" placeholder="Hizmet adı" required><input type="number" name="duration" placeholder="Dakika"><input type="number" name="capacity" placeholder="Kapasite"><input type="number" step="0.01" name="price" placeholder="Fiyat" value="0"><select name="currency"><option>EUR</option><option>TRY</option><option>USD</option></select></div><button>Hizmeti tanımla</button></form><?php foreach($services as $s):?><p><b><?=htmlspecialchars($s['property_name'])?></b> · <?=htmlspecialchars($s['name'])?> · <?=htmlspecialchars($s['service_type'])?> · <?=htmlspecialchars($s['price'])?> <?=htmlspecialchars($s['currency'])?></p><?php endforeach;?></section><section class="next-module"><h2>Açık görevler</h2><?php foreach($housekeeping as $t):?><p><b>Kat:</b> <?=htmlspecialchars($t['property_name'])?> <?=htmlspecialchars($t['room_number']??'')?> · <?=htmlspecialchars($t['task_type'])?> · <?=htmlspecialchars($t['status'])?> · <?=htmlspecialchars($t['assigned_to']??'')?></p><?php endforeach;?><?php foreach($maintenance as $t):?><p><b>Teknik:</b> <?=htmlspecialchars($t['property_name'])?> <?=htmlspecialchars($t['room_number']??'')?> · <?=htmlspecialchars($t['title'])?> · <?=htmlspecialchars($t['status'])?></p><?php endforeach;?></section><?php supply_end();
